// bikestation/slotN/state -> occupied count. reserved == bike not parked yet.
let state = flow.get('slotState') || {};
let slot = msg.topic.split('/')[1].replace('slot', '');
let st = String(msg.payload).trim().toLowerCase();
state[slot] = st === 'occupied';
flow.set('slotState', state);
let occupied = Object.values(state).filter(v => v === true).length;
msg.payload = occupied + ' Bikes';
return msg;

var s = String(msg.payload).trim().toLowerCase();
msg.payload = s === 'free' ? 'AVAILABLE' : (s === 'reserved' ? 'RESERVED' : (s === 'alarm' ? 'ALARM' : 'IN USE'));
return msg;

