// Station logic: access control, reservations, pickups, theft alarm, LCD, gate, sessions.
// Inputs
//   station/occ              ~5 Hz per slot from the occupancy functions: msg.slot, msg.occupied
//   a tap after the db lookup: msg.tap, msg.payload = [{user_id, display_name, paired, parked_slot}]
//                              (no rows when the lookup failed)
//   station/tick             every 10 s, expires reservations and pickups
//   admin/reset              from the admin page, msg.payload = slot number or 'all'
// Outputs: 1 LCD steps, 2 slot state, 3 gate, 4 session sql, 5 alerts, 6 admin page
//
// Rules: only chips/app users with an account get in, one bike per account.
// A parked bike may only leave after its owner tapped for pickup; otherwise
// the slot goes to 'alarm' and the whole station is locked (no taps, gate
// stays closed) until the alarm is reset on the admin page.
const SLOTS = 4;
const RESERVE_MS = 5 * 60 * 1000;
const PICKUP_MS = 2 * 60 * 1000;
const STABLE = 5;          // equal readings (~1 s) before a slot counts as changed

const occ = flow.get('occupiedStable') || {};      // slot -> true/false, debounced
const res = flow.get('reservations') || {};        // slot -> {uid, userId, name, at}
const pick = flow.get('pickups') || {};            // slot -> {userId, name, at}: owner may take the bike
const alarms = flow.get('alarms') || {};           // slot -> {at}: bike left without pickup
const seen = context.get('seen') || {};            // slot -> {cand, n}

const lcdOut = [], stateOut = [], gateOut = [], sqlOut = [], alertOut = [];
let adminChanged = false;
const sql = (query, params) => sqlOut.push({ query: query, params: params });
const lcd = (steps) => { lcdOut.length = 0; lcdOut.push({ steps: steps }); };
const IDLE = { l1: 'Willkommen!', l2: 'Bitte scannen' };
const later = (step, at) => Object.assign({}, step, { at: at });

// the LCD only has ASCII
function ascii(s) {
    return String(s || '')
        .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue')
        .replace(/Ä/g, 'Ae').replace(/Ö/g, 'Oe').replace(/Ü/g, 'Ue').replace(/ß/g, 'ss')
        .replace(/[^\x20-\x7e]/g, '').trim();
}
const hello = (name) => name ? { l1: 'Hallo ' + name.slice(0, 9), l2: 'Willkommen!' } : { l1: 'Hallo!', l2: 'Willkommen!' };
const locked = () => Object.keys(alarms).length > 0;
const lockScreen = () => {
    const slots = Object.keys(alarms).sort();
    return { l1: 'ALARM Slot ' + slots.join(','), l2: 'Station gesperrt' };
};
// same priority as the occupancy functions
const stateOf = (slot) => alarms[slot] ? 'alarm'
    : pick[slot] ? 'reserved'
    : occ[slot] ? 'occupied'
    : (res[slot] ? 'reserved' : 'free');
const publishState = (slot) => stateOut.push({ topic: 'bikestation/slot' + slot + '/state', payload: stateOf(slot), retain: true });
const alert = (type, slot) => alertOut.push({
    topic: 'bikestation/system/alerts',
    payload: JSON.stringify({ type: type, slot: Number(slot), at: new Date().toISOString() }),
});

function expireOld() {
    const now = Date.now();
    for (const k of Object.keys(res)) {
        if (now - res[k].at > RESERVE_MS) {
            delete res[k];
            sql("UPDATE parking_sessions SET status = 'expired', ended_at = now() WHERE slot = $1 AND status = 'reserved'", [Number(k)]);
            publishState(k);
        }
    }
    for (const k of Object.keys(pick)) {
        if (now - pick[k].at > PICKUP_MS) {
            delete pick[k];
            publishState(k);
        }
    }
}

if (msg.topic === 'station/tick') {
    expireOld();
    adminChanged = true;   // keeps the admin page current after a reload
}
else if (msg.topic === 'station/occ') {
    const slot = Number(msg.slot);
    const isOcc = msg.occupied === true;
    const s = seen[slot] || { cand: null, n: 0 };
    if (s.cand === isOcc) s.n++; else { s.cand = isOcc; s.n = 1; }
    seen[slot] = s;

    if (s.n >= STABLE && occ[slot] !== isOcc) {
        const before = occ[slot];
        occ[slot] = isOcc;
        if (isOcc && res[slot]) {
            // the reserved bike has arrived
            const r = res[slot];
            delete res[slot];
            sql("UPDATE parking_sessions SET status = 'parked', parked_at = now() WHERE slot = $1 AND status = 'reserved'", [slot]);
            lcd([{ l1: 'Secured: Slot ' + slot, l2: r.name ? 'Danke ' + r.name.slice(0, 10) : 'Danke!', at: 0 }, later(IDLE, 10000)]);
        } else if (!isOcc && before === true) {
            if (pick[slot]) {
                // the owner took the bike
                delete pick[slot];
                sql("UPDATE parking_sessions SET status = 'done', ended_at = now() WHERE slot = $1 AND status = 'parked'", [slot]);
                publishState(slot);
            } else if (!alarms[slot]) {
                // a bike left without pickup: alarm, lock the station
                alarms[slot] = { at: Date.now() };
                publishState(slot);
                alert('theft', slot);
                gateOut.push({ payload: 'close' });
                lcd([later(lockScreen(), 0)]);
                adminChanged = true;
            }
        }
    }
    expireOld();
}
else if (msg.topic === 'admin/reset') {
    const which = String(msg.payload) === 'all' ? Object.keys(alarms) : [String(Number(msg.payload))];
    for (const k of which) {
        if (!alarms[k]) continue;
        delete alarms[k];
        // the bike is gone: close its session so the owner can park again
        sql("UPDATE parking_sessions SET status = 'done', ended_at = now() WHERE slot = $1 AND status = 'parked'", [Number(k)]);
        publishState(k);
        alert('alarm_cleared', k);
        adminChanged = true;
    }
    if (adminChanged) lcd([later(locked() ? lockScreen() : IDLE, 0)]);
}
else if (msg.tap) {
    const t = msg.tap;
    const row = Array.isArray(msg.payload) && msg.payload[0] ? msg.payload[0] : {};
    const name = ascii(row.display_name);

    if (row.paired) {
        lcd([{ l1: 'Chip verknuepft', l2: name ? 'Hallo ' + name.slice(0, 10) : '', at: 0 },
             later(locked() ? lockScreen() : IDLE, 10000)]);
    } else if (locked()) {
        lcd([{ l1: 'Station gesperrt', l2: 'Alarm aktiv', at: 0 }, later(lockScreen(), 8000)]);
    } else if (!row.user_id) {
        lcd([{ l1: 'Karte unbekannt', l2: 'In App verknuepfen', at: 0 }, later(IDLE, 8000)]);
    } else {
        const mine = Object.keys(res).find((k) => res[k].uid === t.uid || res[k].userId === row.user_id);
        const action = t.action || (row.parked_slot ? 'pickup' : 'park');

        if (action === 'pickup') {
            if (!row.parked_slot) {
                lcd([later(hello(name), 0), { l1: 'Kein Rad', l2: 'geparkt', at: 2000 }, later(IDLE, 10000)]);
            } else {
                // the owner's slot blinks blue until the bike is out
                const slot = row.parked_slot;
                pick[slot] = { userId: row.user_id, name: name, at: Date.now() };
                publishState(slot);
                lcd([later(hello(name), 0), { l1: 'Rad in Slot ' + slot, l2: 'Gute Fahrt!', at: 2000 }, later(IDLE, 12000)]);
                gateOut.push({ payload: 'open' });
            }
        } else if (row.parked_slot) {
            // one bike per account
            lcd([later(hello(name), 0), { l1: 'Du hast schon', l2: 'ein Rad: Slot ' + row.parked_slot, at: 2000 }, later(IDLE, 10000)]);
        } else if (mine) {
            // already has a reservation: show it again and give it a fresh 5 min
            res[mine].at = Date.now();
            sql("UPDATE parking_sessions SET expires_at = now() + make_interval(secs => $2) WHERE slot = $1 AND status = 'reserved'", [Number(mine), RESERVE_MS / 1000]);
            lcd([later(hello(name), 0), { l1: 'Park at Slot ' + mine, l2: 'Gate ist offen', at: 2000 }, later(IDLE, 12000)]);
            gateOut.push({ payload: 'open' });
        } else {
            let free = null;
            for (let i = 1; i <= SLOTS; i++) { if (!occ[i] && !res[i] && !alarms[i]) { free = i; break; } }
            if (!free) {
                lcd([later(hello(name), 0), { l1: 'Station Full!', l2: 'Kein Platz frei', at: 2000 }, later(IDLE, 12000)]);
            } else {
                res[free] = { uid: t.uid, userId: row.user_id, name: name, at: Date.now() };
                publishState(free);
                sql("WITH stale AS (UPDATE parking_sessions SET status = 'expired', ended_at = now() WHERE slot = $3 AND status = 'reserved') " +
                    "INSERT INTO parking_sessions (uid, user_id, slot, status, reserved_at, expires_at) " +
                    "VALUES ($1, $2, $3, 'reserved', now(), now() + make_interval(secs => $4))",
                    [t.uid, row.user_id, free, RESERVE_MS / 1000]);
                lcd([later(hello(name), 0), { l1: 'Park at Slot ' + free, l2: 'Gate ist offen', at: 2000 }, later(IDLE, 12000)]);
                gateOut.push({ payload: 'open' });
            }
        }
    }
}

flow.set('occupiedStable', occ);
flow.set('reservations', res);
flow.set('pickups', pick);
flow.set('alarms', alarms);
context.set('seen', seen);

let adminOut = null;
if (adminChanged) {
    const slots = {};
    for (let i = 1; i <= SLOTS; i++) slots[i] = stateOf(i);
    adminOut = { topic: 'admin', payload: { alarms: alarms, slots: slots, locked: locked() } };
}
return [lcdOut, stateOut, gateOut, sqlOut, alertOut, adminOut];

