@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');

.v-main {
  background-image: url('https://images.hdqwalls.com/wallpapers/landscape-alpine-mountains-landscape-5k-1k.jpg');
  background-size: cover;
  background-repeat: no-repeat;
  background-attachment: fixed;
}

.v-main::before {
  content: '';
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.08);
  pointer-events: none;
  z-index: 0;
}

body {
  font-family: 'Inter', sans-serif !important;
}

.nrdb-ui-group .v-card {
  background: rgba(255, 255, 255, 0.1) !important;
  backdrop-filter: blur(40px) saturate(180%) !important;
  -webkit-backdrop-filter: blur(40px) saturate(180%) !important;
  border: 0.5px solid rgba(255, 255, 255, 0.3) !important;
  border-top: 0.5px solid rgba(255, 255, 255, 0.5) !important;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.08), inset 0 0.5px 0 rgba(255, 255, 255, 0.6) !important;
  border-radius: 16px !important;
}

.room-blaue-box .v-card { border-left: 4px solid #0094CE !important; }
.room-gruene-box .v-card { border-left: 4px solid #3a9e3a !important; }

.last-update-bar {
  display: flex;
  gap: 16px;
  align-items: center;
  padding: 4px 8px;
  font-size: 13px;
}
.lu-item {
  display: flex;
  align-items: center;
  gap: 6px;
}
.lu-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  display: inline-block;
}
.lu-name {
  color: rgba(255,255,255,0.7);
  font-weight: 500;
}
.lu-time {
  color: #fff;
  font-weight: 600;
}

/* ---------- user kiosk pane ---------- */
.kiosk-hero .v-card {
  background: rgba(13, 15, 18, 0.55) !important;
  border: 1px solid rgba(255, 255, 255, 0.18) !important;
  box-shadow: 0 18px 50px rgba(0, 0, 0, 0.35) !important;
}
.kiosk-hero-card .v-card {
  background: rgba(13, 15, 18, 0.55) !important;
  border: 1px solid rgba(255, 255, 255, 0.18) !important;
  box-shadow: none !important;
}

