// distance -> slot state (~5 Hz), plus the raw occupancy for the station
// logic (output 3). The published state is not the occupancy: this function
// republishes ~5x per second, so every state the station logic sets has to
// be decided here too, or it would be overwritten within one cycle:
//   alarm     the bike left without pickup (station locked)
//   reserved  pickup allowed (bike still there) or a reservation (slot empty)
// A 999 (no echo) is not a reading and changes nothing, so a broken sensor
// cannot raise a theft alarm.
var SLOT = '1';
var dist = parseFloat(msg.payload);
var distMsg = { topic: msg.topic, payload: dist };
if (isNaN(dist) || dist >= 999) return [null, distMsg, null];
var occupied = dist < 5;
var alarms = flow.get('alarms') || {};
var pickups = flow.get('pickups') || {};
var reservations = flow.get('reservations') || {};
var state = alarms[SLOT] ? 'alarm'
          : pickups[SLOT] ? 'reserved'
          : occupied ? 'occupied'
          : (reservations[SLOT] ? 'reserved' : 'free');
return [
    { topic: 'bikestation/slot' + SLOT + '/state', payload: state, retain: true },
    distMsg,
    { topic: 'station/occ', slot: Number(SLOT), occupied: occupied },
];

// distance -> slot state (~5 Hz), plus the raw occupancy for the station
// logic (output 3). The published state is not the occupancy: this function
// republishes ~5x per second, so every state the station logic sets has to
// be decided here too, or it would be overwritten within one cycle:
//   alarm     the bike left without pickup (station locked)
//   reserved  pickup allowed (bike still there) or a reservation (slot empty)
// A 999 (no echo) is not a reading and changes nothing, so a broken sensor
// cannot raise a theft alarm.
var SLOT = '2';
var dist = parseFloat(msg.payload);
var distMsg = { topic: msg.topic, payload: dist };
if (isNaN(dist) || dist >= 999) return [null, distMsg, null];
var occupied = dist < 5;
var alarms = flow.get('alarms') || {};
var pickups = flow.get('pickups') || {};
var reservations = flow.get('reservations') || {};
var state = alarms[SLOT] ? 'alarm'
          : pickups[SLOT] ? 'reserved'
          : occupied ? 'occupied'
          : (reservations[SLOT] ? 'reserved' : 'free');
return [
    { topic: 'bikestation/slot' + SLOT + '/state', payload: state, retain: true },
    distMsg,
    { topic: 'station/occ', slot: Number(SLOT), occupied: occupied },
];

// distance -> slot state (~5 Hz), plus the raw occupancy for the station
// logic (output 3). The published state is not the occupancy: this function
// republishes ~5x per second, so every state the station logic sets has to
// be decided here too, or it would be overwritten within one cycle:
//   alarm     the bike left without pickup (station locked)
//   reserved  pickup allowed (bike still there) or a reservation (slot empty)
// A 999 (no echo) is not a reading and changes nothing, so a broken sensor
// cannot raise a theft alarm.
var SLOT = '3';
var dist = parseFloat(msg.payload);
var distMsg = { topic: msg.topic, payload: dist };
if (isNaN(dist) || dist >= 999) return [null, distMsg, null];
var occupied = dist < 5;
var alarms = flow.get('alarms') || {};
var pickups = flow.get('pickups') || {};
var reservations = flow.get('reservations') || {};
var state = alarms[SLOT] ? 'alarm'
          : pickups[SLOT] ? 'reserved'
          : occupied ? 'occupied'
          : (reservations[SLOT] ? 'reserved' : 'free');
return [
    { topic: 'bikestation/slot' + SLOT + '/state', payload: state, retain: true },
    distMsg,
    { topic: 'station/occ', slot: Number(SLOT), occupied: occupied },
];

// distance -> slot state (~5 Hz), plus the raw occupancy for the station
// logic (output 3). The published state is not the occupancy: this function
// republishes ~5x per second, so every state the station logic sets has to
// be decided here too, or it would be overwritten within one cycle:
//   alarm     the bike left without pickup (station locked)
//   reserved  pickup allowed (bike still there) or a reservation (slot empty)
// A 999 (no echo) is not a reading and changes nothing, so a broken sensor
// cannot raise a theft alarm.
var SLOT = '4';
var dist = parseFloat(msg.payload);
var distMsg = { topic: msg.topic, payload: dist };
if (isNaN(dist) || dist >= 999) return [null, distMsg, null];
var occupied = dist < 5;
var alarms = flow.get('alarms') || {};
var pickups = flow.get('pickups') || {};
var reservations = flow.get('reservations') || {};
var state = alarms[SLOT] ? 'alarm'
          : pickups[SLOT] ? 'reserved'
          : occupied ? 'occupied'
          : (reservations[SLOT] ? 'reserved' : 'free');
return [
    { topic: 'bikestation/slot' + SLOT + '/state', payload: state, retain: true },
    distMsg,
    { topic: 'station/occ', slot: Number(SLOT), occupied: occupied },
];

var s = String(msg.payload||'').trim().split(/\s+/);
var idle = parseInt(s[4]||'0',10);
var total = 0;
for (var i=1;i<s.length;i++){ var v=parseInt(s[i]||'0',10); if(!isNaN(v)) total+=v; }
if (isNaN(idle) || total<=0) return null;
var last = context.get('last') || null;
context.set('last',{t:total,idle:idle});
if (!last) return null;
var dt = total - last.t, di = idle - last.idle;
if (dt<=0 || di<0 || di>dt) return null;
var cpuPct = Math.round((1-(di/dt))*1000)/10;
if (cpuPct<0) cpuPct=0; if (cpuPct>100) cpuPct=100;
return {payload: cpuPct};

var parts = String(msg.payload||'').trim().split(/\s+/);
if (parts.length < 2) return null;
var tot = parseInt(parts[0],10), avail = parseInt(parts[1],10);
if (isNaN(tot) || isNaN(avail) || tot<=0) return null;
if (avail<0) avail=0; if (avail>tot) avail=tot;
var pct = Math.round((1-(avail/tot))*1000)/10;
if (pct<0) pct=0; if (pct>100) pct=100;
return {payload: pct};

// bikestation/slotN/state -> availability for the user kiosk pane.
// An 'alarm' slot is not available, and any alarm locks the station.
let s = flow.get('slotState') || {};
let m = (msg.topic || '').match(/slot(\d+)/);
if (m) {
  const st = String(msg.payload).trim().toLowerCase();
  s[m[1]] = st === 'occupied' || st === 'alarm';
  flow.set('slotState', s);
}
let free = 0;
for (let i = 1; i <= 4; i++) { if (s[i] !== true) free++; }
const locked = Object.keys(flow.get('alarms') || {}).length > 0;
return { topic: 'kiosk', payload: { free: locked ? 0 : free, total: 4, locked: locked } };

// Proof-of-life tap on the raw distance feed. Records the arrival
// time per ESP32, then passes the message on untouched.
// ESP32-1 drives slot1/slot2, ESP32-2 drives slot3/slot4.
const owner = { slot1: 'esp1', slot2: 'esp1',
                slot3: 'esp2', slot4: 'esp2' };
const slot = String(msg.topic || '').split('/')[1];
const seen = flow.get('espSeen') || {};
if (owner[slot]) {
    seen[owner[slot]] = Date.now();
    flow.set('espSeen', seen);
}
return msg;

// A healthy ESP32 publishes roughly twice a second, so 20s without
// a single message means it is off, booting, or its MQTT client is
// wedged. Ping is not used: a rebooting board answers ICMP before it
// reconnects, so it would look healthy while publishing nothing.
const LIMIT = 20;
const seen = flow.get('espSeen') || {};
const now = Date.now();
const out = [];
for (const d of [
        { id: 'esp1', label: 'ESP32-1', slots: 'Slots 1-2' },
        { id: 'esp2', label: 'ESP32-2', slots: 'Slots 3-4' }]) {
    const t = seen[d.id];
    const secs = t ? Math.round((now - t) / 1000) : null;
    const online = secs !== null && secs <= LIMIT;
    out.push({
        topic: d.id,
        payload: {
            label: d.label,
            slots: d.slots,
            online: online,
            secs: secs,
            text: online ? 'ONLINE'
                 : secs === null ? 'NO DATA' : 'OFFLINE ' + secs + 's'
        }
    });
}
return [out[0], out[1]];

// Input : bikestation/entrance/nfc/tap
// out0   : the tap unchanged, for the slot-reservation logic
// out1   : local wall-clock time for the dashboard card
//
// Arrival time on the Pi is used rather than any timestamp in the
// payload: the ESP32 has no RTC, so its clock is only meaningful
// after an NTP sync and reads 0/epoch before that.
// hour12:false keeps the 24h format whatever the container locale is.
const stamp = new Date().toLocaleTimeString([], {
    hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false
});
return [msg, { topic: 'rfid/last-tap', payload: stamp }];

// raw MQTT message -> row in the telemetry table (ts defaults to now())
msg.params = [msg.topic, msg.payload];
return msg;

// tap (chip or app) -> params for the db lookup of who it is.
// App taps carry {"uid":"APP-<user>","action":"park"|"pickup"}.
let p = msg.payload;
if (typeof p === 'string') {
    try { p = JSON.parse(p); } catch (e) { p = { uid: p }; }
}
const uid = String((p && p.uid) || '').trim();
if (!uid) return null;
msg.tap = {
    uid: uid,
    action: p.action === 'park' || p.action === 'pickup' ? p.action : null,
    source: p.source || 'chip',
};
msg.params = [uid];
delete msg.query;
return msg;

// msg.steps = [{l1, l2, at}] -> shows each step at its offset (ms) and
// cancels a sequence that was still running.
// The ESP wraps at the last space within the first 16 characters, so line 1
// is cut to 15 characters and padded to 16: line 2 then starts on row 2.
const pad = (s) => (String(s || '').slice(0, 15) + ' '.repeat(16)).slice(0, 16);
(context.get('timers') || []).forEach(clearTimeout);
const timers = [];
for (const s of msg.steps || []) {
    const text = s.l2 ? pad(s.l1) + String(s.l2).slice(0, 16) : String(s.l1 || '').slice(0, 16);
    const out = { topic: 'bikestation/entrance/oled/display', payload: text };
    if (!s.at) node.send(out);
    else timers.push(setTimeout(() => node.send(out), s.at));
}
context.set('timers', timers);
return null;

// 'open' -> open the gate and close it again after OPEN_MS. Another open
// while it is up restarts the timer instead of closing early.
// 'close', or any open while a theft alarm is active -> close right away.
const OPEN_MS = 8000;
const alarms = flow.get('alarms') || {};
clearTimeout(context.get('closeTimer'));
if (msg.payload !== 'open' || Object.keys(alarms).length > 0) {
    node.send({ topic: 'bikestation/entrance/gate', payload: 'close' });
    return null;
}
node.send({ topic: 'bikestation/entrance/gate', payload: 'open' });
context.set('closeTimer', setTimeout(() => {
    node.send({ topic: 'bikestation/entrance/gate', payload: 'close' });
}, OPEN_MS));
return null;
